"""Generate the auditable research report from completed benchmark evidence."""
from pathlib import Path
import json,hashlib,shutil,datetime,csv,sys
import numpy as np,pandas as pd
import champion_market_common_20261031 as c
REPORT=c.ROOT/'research/reports/champion_vs_market_20261031.md'

def table(x,cols,n=12):
 def fmt(v):return f'{v:.4f}' if isinstance(v,(float,np.floating)) else str(v)
 return '\n'.join(['| '+' | '.join(cols)+' |','| '+' | '.join(['---']*len(cols))+' |']+['| '+' | '.join(fmt(v) for v in row)+' |' for row in x[cols].head(n).itertuples(index=False,name=None)])

def runtime_summary():
 records=[]
 for family in ['tabular','sequence']:
  for p in (c.OUT/family).glob('*_audit.json'):
   r=json.loads(p.read_text());name=r.get('algorithm',r.get('architecture',p.name.split('__')[0]));records.append(dict(family=family,model=name,objective=r.get('objective','balanced'),year=r.get('year'),seed=r.get('seed'),seconds=r.get('seconds',np.nan),train_rows=r.get('train_rows'),max_training_endpoint=r.get('max_training_endpoint')))
 x=pd.DataFrame(records);x.to_csv(c.OUT/'fit_registry.csv',index=False);summary=x.groupby(['family','model']).agg(distinct_recorded_fits=('model','size'),seconds=('seconds',lambda v:v.sum(min_count=1)),max_train_rows=('train_rows','max')).reset_index();summary.to_csv(c.OUT/'runtime_summary.csv',index=False);return summary

def main():
 full=pd.read_csv(c.OUT/'full/sector_summary.csv');seq=pd.read_csv(c.OUT/'sequence/sector_summary.csv');decision=json.loads((c.OUT/'full/decision.json').read_text());sd=json.loads((c.OUT/'sequence/decision.json').read_text());dev=pd.read_csv(c.OUT/'full/development_deltas.csv');selected=decision['selected_by_development'];runtime=runtime_summary();support=json.loads((c.OUT/'full/coverage.json').read_text());ssupport=json.loads((c.OUT/'sequence/coverage.json').read_text());ranks=dev.sort_values('attainment3',ascending=False).model.head(5).tolist();ranks=list(dict.fromkeys([c.ANCHOR,selected]+ranks+dev.sort_values('rank_ic',ascending=False).model.head(5).tolist()));display=full[full.model.isin(ranks)].sort_values(['period','attainment3'],ascending=[True,False]);bestseq=seq[seq.model.str.startswith('sequence__')|seq.model.eq(c.ANCHOR)];bounds=pd.read_csv(c.OUT/'full/familywise_bounds.csv');cal=pd.read_csv(c.OUT/'full/calibration_summary.csv');stability=pd.read_csv(c.OUT/'full/stability_summary.csv');scope=json.loads((c.OUT/'portfolio_scope.json').read_text());portfolio=pd.read_csv(c.OUT/'portfolio_paired_comparisons.csv') if (c.OUT/'portfolio_paired_comparisons.csv').exists() else pd.DataFrame();anchorindex=portfolio[portfolio.model.eq(c.ANCHOR)&portfolio.benchmark.eq('NIFTY_500')&portfolio.cost_bps.eq(25)] if len(portfolio) else portfolio
 lines=['# Champion versus market alternatives: completed retrospective benchmark','',f'Generated {datetime.datetime.now(datetime.timezone.utc).isoformat()}. NSE/BSE equities only. Research protocol committed before outcome inspection.','',f'**Serving champion retained.** Development selected `{selected}` in the full cohort and `{sd["selected_by_development"]}` in the sequence cohort. Full-family statistical/exposed gate pass: **{decision["passes_familywise_and_exposed"]}**; sequence-family pass: **{sd["passes_familywise_and_exposed"]}**. These are retrospective diagnostics, not a production-promotion or market-leadership certificate.','', '## What was actually tested','',f'- Full cohort: {len(json.loads((c.OUT/"full/evaluation_support.json").read_text())["models"])} score policies, {support["stocks"]:,} issuers, {support["dates"]} prediction dates, {support["profiles"]} profiles and {support["sectors"]} sectors; {support["rows"]:,} guarded outcome rows.',f'- Nine tabular algorithms each trained on return and balanced objectives; annual mature-label training, fixed whole-query cap, three seeds for stochastic estimators.',f'- Sequence cohort: {ssupport["stocks"]:,} matched issuers, six pinned author-code architectures with three seeds, plus two same-input tabular controls. The cohort is an adaptation test, not a reproduction of overseas paper results.','- Fifteen transparent factor policies, prior related-policy variants, neutral/random controls, ten official NSE TRI histories and explicitly price-only BSE500.','- Rank IC, exact tie-aware pair accuracy, NDCG3/10/20, goal attainment, selected-stock XIRR/drawdown/shortfall, loss frequency, cross-asset tail, profile/sector/year/regime/liquidity slices, snapshot stability, mature-only calibration, actual SIP portfolio cashflows and costs.','', '## Main stock-ranking results','', 'Each row averages sector/profile queries within a date, then dates. XIRR is median selected-stock XIRR within each query, not the XIRR of a combined portfolio. Drawdown is mean selected-asset drawdown; less negative is better. Pair accuracy excludes tied outcomes and gives half credit to tied scores. Constant-score IC is undefined.','',table(display,['period','model','rank_ic','pair_accuracy','attainment3','xirr3','drawdown3','ndcg3'],30),'', 'The complete tables include every compared policy, including poor results. The displayed challengers are selected by development results only; their exposed rows are diagnostics, not a fresh contest.','', '## Foreign architectures on a matched population','',table(bestseq.sort_values(['period','attainment3'],ascending=[True,False]),['period','model','rank_ic','pair_accuracy','attainment3','drawdown3'],24),'', 'Same-input Ridge and LightGBM controls use the same short OHLCV/profile/context representation. Comparisons with the full-feature champion use matched issuers but different feature sets. HIST concepts are retrospective sectors; no historical supply-chain graph was fabricated.','', '## Selection uncertainty and decision','', 'Selection uses development only and is written before exposed metric computation. Both365- and730-day circular date-block bootstraps use4000 resamples and a simultaneous maximum over all candidates within the cohort family. The familywise hurdle is incremental relative to the frozen champion, not an absolute minimum acceptable IC. Neutral undefined IC is excluded from the IC family only. The final diagnostic additionally uses97.5%maximum floors for each of the two primary endpoints, conservatively controlling the either-endpoint selection rule; per-metric95%floors remain reported. Block lengths exceeding available temporal history are unavailable, never zero uncertainty.','',table(bounds[(bounds.model.eq(selected) if selected!=c.ANCHOR else bounds.model.isin(ranks[1:3]))&bounds.period.eq('development')],['model','metric','block_days','delta','familywise_noise_floor','simultaneous_lower95'],18),'', 'Risk noninferiority is a point-estimate gate, not a powered drawdown noninferiority trial. There are few independent decision dates and overlapping12-month outcomes. No new strategy was deployed.','', '## Investor cashflows and official indices','',f'{scope["models"]} score policies were simulated on base7500 with global top20 and sector top3/equal-sector capital policies. Planned portfolio observations before four cost scenarios: {scope["planned_queries"]:,}. Completed cost rows: {scope["completed_cost_rows"]:,}; failure records: {scope["failure_records"]:,}. Missing selected histories and unresolved corporate actions block entire observations. Failures are evidence limits rather than zero returns.', '', 'Stock portfolio paths use recovered provider Adj Close with fractional units; official NSE indices use gross TRI. Costs of0/10/25/50bps apply to each purchase and the terminal sale. These are research proxies, not certified fund NAVs or exact Indian tax/impact estimates. BSE500 price-only results exclude dividends. Index prelaunch histories are separately labelled backfilled; live-only summaries are provided. Weekly contributions that cannot execute before the endpoint are flagged.','', 'Champion minus Nifty500 on matched valid dates at25bps per buy/sale:', '',table(anchorindex,['period','policy','matched_dates','xirr_delta','goal_hit_delta','tw_max_drawdown_delta','tw_sharpe_rf0_delta'],8) if len(anchorindex) else 'No valid matched champion/Nifty500 portfolio observations. A benchmark victory cannot be claimed.','', 'The mean XIRR across overlapping forward cohorts is not a chainable strategy CAGR. Daily flow-adjusted portfolio drawdown is separate from individual-stock drawdown. Risk ratios labelled RF0 use zero risk-free return; IIMA four-factor OLS exposures are descriptive and use its separate RF series. The factor library ends December2025 and can be retrospectively revised; insufficient matched daily history is flagged.','', '## Calibration and product stability','',table(cal[cal.model.isin(ranks[:5])],['period','model','brier','climatology_brier','logloss','ece10'],12),'', 'Calibrations use earlier out-of-time scores and outcomes matured strictly before the prediction date, at least two historical prediction dates and both labels. No raw rank is presented as a probability. Later exposed calibrations can include earlier exposed outcomes once mature under the fixed prequential rule. ECE uses fixed ten bins and is descriptive.','',table(stability[stability.model.isin(ranks[:5])],['period','model','top3_churn','kendall_tau'],12),'', 'Stability ranks the full feature-available cohort, including stocks without evaluable future labels. It measures consecutive available snapshots, not daily champion replay or evidence that a particular hysteresis margin passes its earlier leader-lag gate.','', '## Coverage, cost and reproducibility','',table(runtime,['family','model','distinct_recorded_fits','seconds','max_train_rows'],24),'', 'Runtime is observed shared-machine time, not a hardware-normalized speed contest. Fit receipts record exact seeds, training endpoints, key hashes and parameters. Saved-weight inference is checked against original valid-row predictions with float32 numerical tolerance; source panels, weights and raw provider/index caches remain local. The public evidence bundle contains protocols, code, licences, acquisition hashes, audit receipts and aggregate/pairwise results. External data providers and pinned source snapshots are required to reconstruct the full local panel.','', 'See [literature review](champion_vs_market_literature_20261031.md), [56 primary references](../literature/20261031/REFERENCES.md), the experiment README and evidence manifest. Commercial scoring platforms without matched historical score archives remain **untested**, not defeated.','', '## Material limits','', '- Current-survivor identities, retrospective sectors and incomplete historical delisting/terminal-price recovery remain. This is not survivorship-free validation.','-2024â€“2025 was already exposed in earlier research; there is no fresh historical holdout here. The prospective ledger still needs eligible fresh champion inputs.','- Fundamentals/quality/value are represented by real index investment comparators, not a fabricated point-in-time stock accounting panel.','- A small fixed-budget foreign-model adaptation does not bound the best possible overseas architecture performance. Reviewed but unexecuted architectures are explicitly listed in the literature report.','- Missing/blocked portfolio observations can be selective. Only common valid dates are compared, with their counts shown; these results cannot establish unconditional investable superiority.','- No claim of beating every Indian commercial ranking service is supported by these data.']
 REPORT.write_text('\n'.join(lines)+'\n',encoding='utf-8');print('REPORT',REPORT,flush=True)

if __name__=='__main__':main()
